class Stack:
    def __init__(self):
        self._items = []

    def push(self, val):
        self._items.append(val)

    def pop(self):
        if not self._items:
            return "EMPTY"
        return self._items.pop()

    def peek(self):
        if not self._items:
            return "EMPTY"
        return self._items[-1]

    def size(self):
        return len(self._items)

    def is_empty(self):
        return len(self._items) == 0

