head = reverse_in_place(head)
print(f"Reversed: {fmt(head)}")

class HashTable:
    def __init__(self, cap):
        self.cap = cap
        self.buckets = [[] for _ in range(cap)]

    def _hash(self, key):
        return sum(ord(c) for c in key) % self.cap

    def put(self, key, val):
        bucket = self.buckets[self._hash(key)]
        for pair in bucket:
            if pair[0] == key:
                pair[1] = val
                return
        bucket.append([key, val])

    def get(self, key):
        bucket = self.buckets[self._hash(key)]
        for k, v in bucket:
            if k == key:
                return v
        return "MISS"

    def delete(self, key):
        bucket = self.buckets[self._hash(key)]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket.pop(i)
                return "OK"
        return "MISS"

    def bucket_str(self, idx):
        bucket = self.buckets[idx]
        if not bucket:
            return "EMPTY"
        return ", ".join(f"{k}={v}" for k, v in bucket)

