if root is None:
    print("EMPTY")
else:
    pre, ino, post = [], [], []
    preorder(root, pre)
    inorder(root, ino)
    postorder(root, post)
    lvl = level_order(root)
    print("Preorder: " + " ".join(pre))
    print("Inorder: " + " ".join(ino))
    print("Postorder: " + " ".join(post))
    print("Level: " + " ".join(lvl))

class BSTNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        def _ins(node):
            if node is None:
                return BSTNode(val)
            if val < node.val:
                node.left = _ins(node.left)
            elif val > node.val:
                node.right = _ins(node.right)
            return node
        self.root = _ins(self.root)

    def search(self, val):
        curr = self.root
        while curr is not None:
            if val == curr.val:
                return "FOUND"
            curr = curr.left if val < curr.val else curr.right
        return "NOT_FOUND"

    def height(self):
        def _h(node):
            if node is None:
                return 0
            return 1 + max(_h(node.left), _h(node.right))
        return _h(self.root)

    def inorder(self):
        out = []
        def _walk(node):
            if node:
                _walk(node.left)
                out.append(str(node.val))
                _walk(node.right)
        _walk(self.root)
        return " ".join(out) if out else "EMPTY"

    def is_valid(self):
        def _val(node, lo, hi):
            if node is None:
                return True
            if not (lo < node.val < hi):
                return False
            return _val(node.left, lo, node.val) and _val(node.right, node.val, hi)
        return _val(self.root, float("-inf"), float("inf"))

