from collections import deque

v, e = map(int, input().split())
adj = [[] for _ in range(v)]
for _ in range(e):
    a, b = map(int, input().split())
    adj[a].append(b)
    adj[b].append(a)
for lst in adj:
    lst.sort()

src, dst = map(int, input().split())

visited = [False] * v
comp = 0
for start in range(v):
    if not visited[start]:
        comp += 1
        stack = [start]
        visited[start] = True
        while stack:
            node = stack.pop()
            for nb in adj[node]:
                if not visited[nb]:
                    visited[nb] = True
                    stack.append(nb)

parent = {src: None}
q = deque([src])
while q:
    cur = q.popleft()
    if cur == dst:
        break
    for nb in adj[cur]:
        if nb not in parent:
            parent[nb] = cur
            q.append(nb)

print(f"Components: {comp}")
if dst not in parent:
    print("Shortest Path: UNREACHABLE")
else:
    path = []
    cur = dst
    while cur is not None:
        path.append(str(cur))
        cur = parent[cur]
    path.reverse()
    print("Shortest Path: " + " -> ".join(path))
